import { Icon } from "@/registry/erbium/ui/icon";
import { EmptyHeader, EmptyMedia, EmptyTitle, EmptyDescription } from "@/registry/erbium/ui/empty";
import { Empty } from "@/registry/erbium/ui/empty";

const Example = (args: {
  className: string;
  mediaVariant: "default" | "icon";
  title: string;
  description: string;
}) => (
  <Empty className={`w-80 ${args.className}`}>
    <EmptyHeader>
      <EmptyMedia variant={args.mediaVariant}>
        <Icon name="star" aria-hidden="true" />
      </EmptyMedia>
      <EmptyTitle>{args.title}</EmptyTitle>
      <EmptyDescription>{args.description}</EmptyDescription>
    </EmptyHeader>
  </Empty>
);

export default Example;
